class TickerBook:
    def __init__(self):
        self.root = {}                   # letter -> child node; '#' marks a listed ticker

    def _walk(self, s):
        node = self.root
        for ch in s:
            node = node.get(ch)
            if node is None:
                return None
        return node

    def has(self, ticker):
        node = self._walk(ticker)
        return bool(node and node.get('#'))

    def add(self, ticker):
        node = self.root
        for ch in ticker:
            node = node.setdefault(ch, {})
        node['#'] = True                 # listed already: nothing changes

    def remove(self, ticker):
        node = self._walk(ticker)
        if node:                         # absent: no change
            node.pop('#', None)          # clear the end mark only

    def longest_listed(self, query):
        node, best = self.root, None
        for i, ch in enumerate(query):
            node = node.get(ch)
            if node is None:
                break
            if node.get('#'):
                best = query[:i + 1]
        return best

    def count_match(self, pattern):
        def go(node, i):
            if i == len(pattern):
                return 1 if node.get('#') else 0
            if pattern[i] == '?':        # any one letter: try every child
                return sum(go(c, i + 1) for k, c in node.items() if k != '#')
            child = node.get(pattern[i])
            return go(child, i + 1) if child else 0
        return go(self.root, 0)

