def run_book(ops):
    book = TickerBook()
    out = []
    for op, arg in ops:
        if op == 'add': book.add(arg)
        elif op == 'remove': book.remove(arg)
        elif op == 'has': out.append(book.has(arg))
        elif op == 'longest': out.append(book.longest_listed(arg))
        else: out.append(book.count_match(arg))
    return out

def big_case(n=100000):
    state = [2026]
    def rnd(m):
        state[0] = (state[0] * 6364136223846793005 + 1442695040888963407) % 2**64
        return (state[0] >> 33) % m
    def word(lo, hi):
        return ''.join('ABCDEFGH'[rnd(8)] for _ in range(lo + rnd(hi - lo + 1)))
    def pattern():
        s = list(word(2, 4))
        for _ in range(1 + rnd(2)):
            s[rnd(len(s))] = '?'
        return ''.join(s)
    book = TickerBook()
    total = hits = longest = 0
    for _ in range(n):
        r = rnd(10)
        if r < 5:
            book.add(word(1, 6))
        elif r < 6:
            book.remove(word(1, 6))
        elif r < 7:
            if book.has(word(1, 6)):
                hits += 1
        elif r < 8:
            longest += len(book.longest_listed(word(1, 8)) or '')
        else:
            total += book.count_match(pattern())
    return [total, hits, longest]

